<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { api,messageOf,query,ui } from '../api'
import { requirementStatuses } from '../planning'
import { taskStatuses } from '../api'
import Pager from './Pager.vue'
import type { RequirementCoverageResult,CoverageTask,CoverageRequirement } from '../planning'
const props=defineProps<{projectId:string;revision:number;disabled?:boolean}>(),emit=defineEmits<{requirement:[id:string];task:[id:string]}>()
const opened=ref(false),project=ref(props.projectId),view=ref('requirements'),check=ref('all'),q=ref(''),offset=ref(0),loading=ref(false),error=ref(''),data=ref<RequirementCoverageResult>(),limit=15
let request=0
const requirements=computed(()=>(data.value?.view==='requirements'?data.value.items:[]) as CoverageRequirement[]),tasks=computed(()=>(data.value?.view==='unlinked_tasks'?data.value.items:[]) as CoverageTask[])
async function load(){if(!opened.value)return;const seq=++request;data.value=undefined;error.value='';if(!project.value){loading.value=false;return;}loading.value=true;try{const result=await api<RequirementCoverageResult>(`/api/projects/${encodeURIComponent(project.value)}/requirements/coverage?${query({view:view.value,coverage:view.value==='requirements'?check.value:'all',q:q.value.trim(),limit,offset:offset.value})}`);if(seq===request)data.value=result}catch(e){if(seq===request)error.value=messageOf(e)}finally{if(seq===request)loading.value=false}}
function toggle(event:Event){opened.value=(event.target as HTMLDetailsElement).open;if(opened.value)void load()}
function apply(){offset.value=0;void load()}
function choose(value:string){view.value=value==='unlinked_tasks'?'unlinked_tasks':'requirements';check.value=value==='unlinked_tasks'?'all':value;apply()}
watch(()=>props.projectId,id=>{project.value=id;offset.value=0;void load()});watch(()=>props.revision,()=>void load())
</script>
<template><details class="surface requirement-coverage" @toggle="toggle"><summary>需求覆盖检查 <span>核对任务关联与待验收项</span></summary><div class="coverage-body"><form class="filter-bar coverage-filters" @submit.prevent="apply"><select v-model="project" aria-label="覆盖检查项目" @change="apply"><option value="" disabled>选择项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select :value="view==='unlinked_tasks'?'unlinked_tasks':check" aria-label="覆盖检查范围" @change="choose(($event.target as HTMLSelectElement).value)"><option value="all">全部有效需求</option><option value="no_tasks">未关联有效任务的需求</option><option value="unlinked_tasks">未关联需求的叶子任务</option><option value="ready_for_acceptance">任务全完成，待人工验收</option><option value="accepted_with_incomplete_tasks">已验收但任务未全完成</option></select><input v-model="q" maxlength="200" aria-label="搜索覆盖检查" placeholder="编号、名称或内容"/><button class="button subtle small" :disabled="loading">查询</button></form><p class="input-hint">仅核对当前直接关联；关联父任务不会自动覆盖其子任务。已作废需求不计入有效覆盖，任务完成也不会自动验收需求。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="loading" class="loading-message">正在核对完整项目…</p><template v-else-if="data"><div class="coverage-counts"><button type="button" @click="choose('no_tasks')"><strong>{{data.summary.requirements_without_tasks}}</strong>未关联任务的需求</button><button type="button" @click="choose('unlinked_tasks')"><strong>{{data.summary.unlinked_leaf_tasks}}</strong>未关联需求的叶子任务</button><button type="button" @click="choose('ready_for_acceptance')"><strong>{{data.summary.ready_for_acceptance}}</strong>待人工验收</button><button type="button" @click="choose('accepted_with_incomplete_tasks')"><strong>{{data.summary.accepted_with_incomplete_tasks}}</strong>已验收但任务未全完成</button></div><p class="input-hint coverage-total">全项目：{{data.summary.active_requirements}} 条有效需求 · {{data.summary.linked_leaf_tasks}} / {{data.summary.leaf_tasks}} 项叶子任务已有直接需求关联</p><div v-if="data.items.length" class="table-scroll"><table><thead><tr><th>{{view==='requirements'?'需求':'叶子任务'}}</th><th>状态</th><th>{{view==='requirements'?'关联任务完成情况':'负责人'}}</th><th class="right">操作</th></tr></thead><tbody v-if="view==='requirements'"><tr v-for="item in requirements" :key="item.id"><td><button type="button" class="table-title" :disabled="disabled" @click="emit('requirement',item.id)">{{item.code}} {{item.title}}</button><small>修订 {{item.revision}}</small></td><td>{{requirementStatuses[item.status]}}</td><td>{{item.done_task_count}} / {{item.task_count}} 项完成<small v-if="item.ready_for_acceptance">请依据验收准则人工核对</small><details v-if="item.linked_tasks.length"><summary>查看关联任务</summary><ul><li v-for="task in item.linked_tasks" :key="task.id"><button type="button" class="text-button" :disabled="disabled" @click="emit('task',task.id)">{{task.wbs_code}} {{task.name}}</button> · {{taskStatuses[task.status]}}</li></ul></details></td><td class="right"><button type="button" class="text-button" :disabled="disabled" @click="emit('requirement',item.id)">查看需求</button></td></tr></tbody><tbody v-else><tr v-for="item in tasks" :key="item.id"><td>{{item.wbs_code}} {{item.name}}</td><td>{{taskStatuses[item.status]}}</td><td>{{item.assignee||'未指定'}}</td><td class="right"><button type="button" class="text-button" :disabled="disabled" @click="emit('task',item.id)">查看任务</button></td></tr></tbody></table></div><p v-else class="empty-state compact">此范围没有待核对项。</p><Pager :offset="offset" :limit="limit" :total="data.total" @change="offset=$event;load()"/></template><p v-else-if="!project" class="empty-state compact">选择项目后核对完整项目的需求与任务关联。</p></div></details></template>
<style scoped>.requirement-coverage{margin-bottom:22px}.requirement-coverage>summary{padding:18px 20px;cursor:pointer;font-weight:600;font-size:14px}.requirement-coverage>summary>span{font-size:11px;color:var(--muted);font-weight:400;margin-left:12px}.coverage-body{padding:0 20px 4px}.coverage-filters{flex-wrap:wrap;margin-bottom:12px}.coverage-filters input{flex:1;min-width:150px}.coverage-filters select{max-width:100%}.coverage-counts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:18px}.coverage-counts button{text-align:left;border:1px solid var(--border);border-radius:4px;padding:12px;color:var(--muted);font-size:11px;background:#f8faff;line-height:1.7}.coverage-counts strong{display:block;color:var(--ink);font-size:21px;font-weight:600}.coverage-counts button:hover{border-color:var(--blue)}.coverage-total{margin:14px 0}.coverage-body table{min-width:620px}.coverage-body td{overflow-wrap:anywhere}.coverage-body details{font-size:11px;margin-top:6px}.coverage-body ul{padding-left:16px;line-height:1.9}.coverage-body .pager{padding-left:0;padding-right:0}@media(max-width:650px){.coverage-body{padding:0 15px}.coverage-counts{grid-template-columns:repeat(2,minmax(0,1fr))}.requirement-coverage>summary>span{display:block;margin:5px 0 0 15px}.coverage-filters select{width:100%}}
</style>
